package org.jlinalg.genetics;

import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.GZIPInputStream;

/** Literal canonical SpliceAI VCF records, including every allele, gene context and missing score. */
public final class SpliceAiVcf {
    private SpliceAiVcf(){ }
    public static final List<String> FIELDS=List.of("ALLELE","SYMBOL","DS_AG","DS_AL","DS_DG","DS_DL","DP_AG","DP_AL","DP_DG","DP_DL");
    private static final List<String> FIXED=List.of("#CHROM","POS","ID","REF","ALT","QUAL","FILTER","INFO");
    public record Limits(long maximumCharacters,long maximumVariants,long maximumAnnotations,int maximumLineCharacters){public Limits{if(maximumCharacters<1||maximumVariants<1||maximumAnnotations<1||maximumLineCharacters<256)throw new IllegalArgumentException("Positive complete-input limits and line capacity>=256 required");}}
    public record Schema(List<String> columns,List<String> spliceAiHeaders){public Schema{columns=List.copyOf(columns);spliceAiHeaders=List.copyOf(spliceAiHeaders);}}
    public record Variant(long row,List<String> originalFields,List<String> annotatedFields,String rawSpliceAi,List<String> sourceReserializedColumns,int annotations,int unannotatedAlleles){public Variant{originalFields=List.copyOf(originalFields);annotatedFields=List.copyOf(annotatedFields);sourceReserializedColumns=List.copyOf(sourceReserializedColumns);}}
    public record Annotation(long row,int index,int alleleNumber,String alternate,String gene,List<String> fields,String maximumObservedScore,String minimumObservedScore,boolean completeScores,boolean completePositions,String state){public Annotation{fields=List.copyOf(fields);}}
    public record Allele(long row,int alleleNumber,String alternate,int annotations,int fullyScoredAnnotations,int missingScoreAnnotations,int nonfiniteScoreAnnotations,List<String> genes,String maximumObservedScore,String minimumObservedScore){public Allele{genes=List.copyOf(genes);}}
    public record Gene(long row,int alleleNumber,String alternate,String gene,int annotations,int fullyScoredAnnotations,List<Integer> annotationIndexes,String maximumObservedScore,String minimumObservedScore){public Gene{annotationIndexes=List.copyOf(annotationIndexes);}}
    public record Summary(Schema schema,long variants,long alternateAlleles,long annotations,long geneGroups,long unannotatedAlleles,long missingScoreAnnotations,long nonfiniteScoreAnnotations,long partialTuples,long annotationsWithoutGene,long sourceReserializedRows,boolean originalInputAudited){ }
    @FunctionalInterface public interface Sink<T>{void accept(T value)throws IOException;}
    public static Summary inspect(Path annotated,Limits limits,Sink<Schema> schema,Sink<Variant> variants,Sink<Annotation> annotations,Sink<Allele> alleles,Sink<Gene> genes)throws IOException{return audit(null,annotated,limits,schema,variants,annotations,alleles,genes);}
    public static Summary audit(Path original,Path annotated,Limits limits,Sink<Schema> schemas,Sink<Variant> variants,Sink<Annotation> annotations,Sink<Allele> alleles,Sink<Gene> genes)throws IOException{
        Budget budget=new Budget(limits);long rows=0,totalAlleles=0,totalAnnotations=0,geneGroups=0,unannotated=0,missing=0,nonfinite=0,partial=0,withoutGene=0,reserialized=0;
        try(Vcf before=original==null?null:new Vcf(original,budget,false);Vcf after=new Vcf(annotated,budget,true)){
            if(before!=null)require(before.columns.equals(after.columns),"SpliceAI source changed VCF sample/column identities");Schema schema=new Schema(after.columns,after.headers);schemas.accept(schema);List<String> fields;
            while((fields=after.next())!=null){require(++rows<=limits.maximumVariants(),"Complete SpliceAI variant capacity exceeded");List<String> previous=before==null?List.of():before.next();require(before==null||previous!=null,"SpliceAI source added input rows");var changed=new ArrayList<String>();
                if(before!=null){for(int i=0;i<5;i++)require(previous.get(i).equals(fields.get(i)),"SpliceAI changed literal variant identity/representation at row "+rows);for(int i=5;i<fields.size();i++){String a=i==7?nonSplice(previous.get(i)):previous.get(i),b=i==7?nonSplice(fields.get(i)):fields.get(i);if(!a.equals(b))changed.add(after.columns.get(i));}if(!changed.isEmpty())reserialized++;}
                List<String> alternatives=Arrays.asList(fields.get(4).split(",",-1));require(alternatives.stream().noneMatch(String::isEmpty)&&new HashSet<>(alternatives).size()==alternatives.size(),"Repeated/empty ALT cannot be assigned unambiguously to SpliceAI's allele-only annotation");totalAlleles=Math.addExact(totalAlleles,alternatives.size());require(totalAlleles<=limits.maximumAnnotations(),"Complete SpliceAI allele capacity exceeded");var aggregates=new ArrayList<Aggregate>();var groups=new ArrayList<LinkedHashMap<String,Aggregate>>();for(String unused:alternatives){aggregates.add(new Aggregate());groups.add(new LinkedHashMap<>());}
                String raw=splice(fields.get(7));int count=0;
                if(raw!=null&&!raw.equals("."))for(String entry:raw.split(",",-1)){
                    require(++totalAnnotations<=limits.maximumAnnotations(),"Complete SpliceAI annotation capacity exceeded");String[] values=entry.split("\\|",-1);require(values.length==10,"Require every canonical SpliceAI field; no field truncation or inferred schema");int a=alternatives.indexOf(values[0]);require(a>=0,"SpliceAI ALLELE does not match a unique literal ALT");boolean completeScores=true,completePositions=true,hasMissing=false,hasNonfinite=false;int missingScores=0,missingPositions=0;Extreme extreme=new Extreme();
                    for(int i=2;i<6;i++){String value=values[i];require(!value.isEmpty(),"Empty SpliceAI DS token is not an inferred missing value");if(value.equals(".")){completeScores=false;hasMissing=true;missingScores++;}else{double score=number(value);if(Double.isFinite(score))extreme.add(value,score);else{completeScores=false;hasNonfinite=true;}}}
                    for(int i=6;i<10;i++){String value=values[i];if(value.equals(".")){completePositions=false;missingPositions++;}else{require(value.matches("[+-]?[0-9]+"),"Invalid literal SpliceAI delta position");try{Long.parseLong(value);}catch(NumberFormatException e){throw new IOException("SpliceAI delta-position integer overflow",e);}}}
                    if(hasMissing)missing++;if(hasNonfinite)nonfinite++;if((missingScores!=0||missingPositions!=0)&&!(missingScores==4&&missingPositions==4))partial++;
                    String state=hasNonfinite?"NONFINITE_SCORES_UNASSESSABLE":!completeScores?"MISSING_SCORES_UNASSESSABLE":!completePositions?"MISSING_POSITIONS_UNASSESSABLE":"SOURCE_SCORES_AND_POSITIONS_PRESENT";int index=++count;annotations.accept(new Annotation(rows,index,a+1,values[0],values[1],Arrays.asList(values),extreme.maximum,extreme.minimum,completeScores,completePositions,state));aggregates.get(a).add(index,values,completeScores,hasMissing,hasNonfinite);
                    if(values[1].isEmpty())withoutGene++;else groups.get(a).computeIfAbsent(values[1],unused->new Aggregate()).add(index,values,completeScores,hasMissing,hasNonfinite);
                }
                int rowUnannotated=0;for(int i=0;i<alternatives.size();i++){Aggregate aggregate=aggregates.get(i);if(aggregate.annotations==0){unannotated++;rowUnannotated++;}alleles.accept(new Allele(rows,i+1,alternatives.get(i),aggregate.annotations,aggregate.fullyScored,aggregate.missing,aggregate.nonfinite,new ArrayList<>(groups.get(i).keySet()),aggregate.extreme.maximum,aggregate.extreme.minimum));for(var entry:groups.get(i).entrySet()){Aggregate g=entry.getValue();geneGroups++;genes.accept(new Gene(rows,i+1,alternatives.get(i),entry.getKey(),g.annotations,g.fullyScored,g.indexes,g.extreme.maximum,g.extreme.minimum));}}
                variants.accept(new Variant(rows,previous,fields,raw==null?"":raw,changed,count,rowUnannotated));
            }
            require(before==null||before.next()==null,"SpliceAI source dropped input rows");return new Summary(schema,rows,totalAlleles,totalAnnotations,geneGroups,unannotated,missing,nonfinite,partial,withoutGene,reserialized,before!=null);
        }
    }
    private static final class Aggregate{int annotations,fullyScored,missing,nonfinite;final List<Integer> indexes=new ArrayList<>();final Extreme extreme=new Extreme();void add(int index,String[] fields,boolean scored,boolean absent,boolean infinite)throws IOException{annotations++;if(scored)fullyScored++;if(absent)missing++;if(infinite)nonfinite++;indexes.add(index);for(int i=2;i<6;i++)if(!fields[i].equals(".")){double value=number(fields[i]);if(Double.isFinite(value))extreme.add(fields[i],value);}}}
    private static final class Extreme{String maximum,minimum;double high,low;void add(String raw,double value){if(maximum==null||value>high){maximum=raw;high=value;}if(minimum==null||value<low){minimum=raw;low=value;}}}
    private static double number(String raw)throws IOException{String s=raw.toLowerCase(Locale.ROOT);require(s.matches("[+-]?(?:(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)(?:e[+-]?[0-9]+)?|nan|inf(?:inity)?)"),"Invalid literal SpliceAI DS token");return switch(s){case "nan","+nan","-nan"->Double.NaN;case "inf","+inf","infinity","+infinity"->Double.POSITIVE_INFINITY;case "-inf","-infinity"->Double.NEGATIVE_INFINITY;default->{try{yield Double.parseDouble(s);}catch(NumberFormatException e){throw new IOException("Invalid SpliceAI DS number",e);}}};}
    private static String splice(String info)throws IOException{String result=null;boolean found=false;for(String token:info.split(";",-1)){if(token.equals("SpliceAI"))throw new IOException("Flag SpliceAI INFO has no canonical annotation value");if(token.startsWith("SpliceAI=")){require(!found,"Repeated SpliceAI INFO entry");found=true;result=token.substring(9);require(!result.isEmpty(),"Empty SpliceAI INFO is not a scored annotation");}}return result;}
    private static String nonSplice(String info)throws IOException{splice(info);var result=new ArrayList<String>();for(String token:info.split(";",-1))if(!token.startsWith("SpliceAI="))result.add(token);return result.isEmpty()?".":String.join(";",result);}
    private static final class Vcf implements AutoCloseable{
        final Lines lines;final List<String> columns,headers;boolean ended;
        Vcf(Path path,Budget budget,boolean annotated)throws IOException{lines=new Lines(path,budget);try{List<String> c=null;var h=new ArrayList<String>();String line;while((line=lines.next())!=null){if(line.startsWith("##INFO=<ID=SpliceAI,")){h.add(line);require(line.contains("Format: "+String.join("|",FIELDS)),"Unrecognized SpliceAI INFO field schema");}if(line.startsWith("##"))continue;if(line.startsWith("#CHROM\t")){c=Arrays.asList(line.split("\t",-1));require(c.size()>=8&&c.subList(0,8).equals(FIXED),"Require complete literal VCF columns");require(c.size()==8||c.get(8).equals("FORMAT"),"VCF FORMAT column differs");var samples=c.size()>9?c.subList(9,c.size()):List.<String>of();require(samples.stream().noneMatch(String::isEmpty)&&new HashSet<>(samples).size()==samples.size(),"Duplicate/empty sample identity");break;}throw new IOException("Unexpected VCF header/data before #CHROM");}require(c!=null&&(!annotated||h.size()==1),"Require one canonical SpliceAI header for annotated VCF");columns=List.copyOf(c);headers=List.copyOf(h);}catch(IOException|RuntimeException e){lines.close();throw e;}}
        List<String> next()throws IOException{if(ended)return null;String line;while((line=lines.next())!=null){if(line.isEmpty())continue;require(!line.startsWith("#"),"Unexpected VCF header inside data rows");List<String> f=Arrays.asList(line.split("\t",-1));require(f.size()==columns.size(),"VCF row/sample width differs");for(int i:new int[]{0,2,3,4})require(!f.get(i).isEmpty(),"Blank literal VCF identity");require(f.get(1).matches("[1-9][0-9]*"),"Require positive literal VCF POS");try{Long.parseLong(f.get(1));}catch(NumberFormatException e){throw new IOException("VCF POS integer overflow",e);}return f;}ended=true;return null;}
        public void close()throws IOException{lines.close();}
    }
    private static final class Budget{final Limits limits;long characters;Budget(Limits limits){this.limits=limits;}void use(int n)throws IOException{require(n<=limits.maximumCharacters()-characters,"Complete decoded SpliceAI VCF character capacity exceeded");characters+=n;}}
    private static final class Lines implements AutoCloseable{final Reader reader;final Budget budget;final char[] buffer=new char[8192];int at,end;boolean afterCR;Lines(Path path,Budget budget)throws IOException{require(Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS),"Require a regular captured SpliceAI VCF");this.budget=budget;InputStream input=new BufferedInputStream(Files.newInputStream(path));try{input.mark(2);int a=input.read(),b=input.read();input.reset();if(a==31&&b==139)input=new GZIPInputStream(input,65536);reader=new InputStreamReader(input,StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT));}catch(IOException|RuntimeException e){input.close();throw e;}}String next()throws IOException{var line=new StringBuilder();for(;;){if(at==end){end=reader.read(buffer);at=0;if(end<0)return line.isEmpty()?null:line.toString();if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("SpliceAI VCF processing interrupted");budget.use(end);}char c=buffer[at++];if(afterCR){afterCR=false;if(c=='\n')continue;}if(c=='\r'){afterCR=true;return line.toString();}if(c=='\n')return line.toString();require(line.length()<budget.limits.maximumLineCharacters(),"Complete SpliceAI VCF line capacity exceeded");line.append(c);}}public void close()throws IOException{reader.close();}}
    private static void require(boolean value,String message)throws IOException{if(!value)throw new IOException(message);}
}
